let charName = '';
if (typeof query === 'string') {
  charName = query.trim();
} else if (typeof query === 'object' && query !== null) {
  charName = query.input || query.name || query.query || JSON.stringify(query);
} else {
  charName = String(query || '');
}
charName = charName.replace(/^["']|["']$/g, '').trim();

if (!charName) {
  return 'Nome de personagem inválido.';
}

try {
  const response = await fetch(`https://api.tibiadata.com/v4/character/${encodeURIComponent(charName)}`);
  const data = await response.json();

  if (!data.character || !data.character.character || !data.character.character.name) {
    return `Personagem "${charName}" não foi encontrado no Tibia oficial.`;
  }

  const c = data.character.character;
  let guildInfo = 'Nenhuma';
  if (c.guild && c.guild.name) {
    guildInfo = `${c.guild.rank || 'Membro'} da ${c.guild.name}`;
  }

  let deathsInfo = 'Nenhuma morte recente registrada';
  if (Array.isArray(data.character.deaths) && data.character.deaths.length > 0) {
    deathsInfo = data.character.deaths.slice(0, 3).map(d => `${d.time}: Morto no level ${d.level} por ${d.reason || (d.killers && d.killers[0] ? d.killers[0].name : 'desconhecido')}`).join(' | ');
  }

  let status = 'offline';
  if (Array.isArray(data.character.other_characters)) {
    const me = data.character.other_characters.find(o => o.name.toLowerCase() === c.name.toLowerCase());
    if (me && me.status) {
      status = me.status;
    }
  }

  return JSON.stringify({
    nome: c.name,
    level: c.level,
    vocacao: c.vocation,
    mundo: c.world,
    status: status,
    residencia: c.residence,
    guilda: guildInfo,
    ultimo_login: c.last_login || 'Nunca',
    status_conta: c.account_status,
    mortes_recentes: deathsInfo
  });
} catch (err) {
  return `Erro ao consultar a API do TibiaData: ${err.message}`;
}

let worldName = '';
if (typeof query === 'string') {
  worldName = query.trim();
} else if (typeof query === 'object' && query !== null) {
  worldName = query.input || query.world || query.name || query.query || JSON.stringify(query);
} else {
  worldName = String(query || '');
}
worldName = worldName.replace(/^["']|["']$/g, '').trim();

if (!worldName) {
  return 'Nome de mundo/servidor inválido.';
}

try {
  const response = await fetch(`https://api.tibiadata.com/v4/world/${encodeURIComponent(worldName)}`);
  const data = await response.json();

  if (!data.world || !data.world.name) {
    return `Mundo/servidor "${worldName}" não foi encontrado no Tibia oficial.`;
  }

  const w = data.world;
  return JSON.stringify({
    mundo: w.name,
    status: w.status,
    jogadores_online: w.players_online,
    tipo_pvp: w.pvp_type,
    localizacao: w.location,
    tipo_servidor: w.server_type,
    battleye: w.battleye_protected ? 'Protegido por BattlEye' : 'Sem BattlEye'
  });
} catch (err) {
  return `Erro ao consultar o mundo no TibiaData: ${err.message}`;
}
